// A small shop to try SQL before bringing own files: 4 tables with keys,
// generated by DuckDB itself (fixed seed, so every user gets the same rows
// and answers can be compared).

/** The demo shop lives in its own schema, like a sample dataset: what the tree shows is what a query says (`demo.orders`). */
export const DEMO_SCHEMA = 'demo'
export const DEMO_TABLES = ['customers', 'products', 'orders', 'order_items']

/**
 * Each demo table's columns. Before v0.13 the shop lived in main without a schema; a saved
 * database still holding all four tables with exactly these columns is the old shop and is moved
 * to `demo` once (src/core/demoMigration.ts). tests/demo.test.ts keeps this list equal to DEMO_SQL.
 */
export const DEMO_COLUMNS: Record<string, string[]> = {
  customers: ['customer_id', 'full_name', 'city', 'signup_date', 'channel'],
  products: ['product_id', 'product_name', 'category', 'price'],
  orders: ['order_id', 'customer_id', 'ordered_at', 'status'],
  order_items: ['order_id', 'line_no', 'product_id', 'quantity'],
}

/**
 * Bare names keep working: `orders` finds `demo.orders` when main has no `orders` of its own.
 * Run once per connection, after the schema exists (src/db/demo.ts).
 */
export const SEARCH_PATH_SQL = `SET search_path = 'main,${DEMO_SCHEMA}'`

export const DEMO_SQL = `
CREATE SCHEMA IF NOT EXISTS demo;
DROP TABLE IF EXISTS demo.order_items;
DROP TABLE IF EXISTS demo.orders;
DROP TABLE IF EXISTS demo.products;
DROP TABLE IF EXISTS demo.customers;

CREATE TABLE demo.customers (
  customer_id INTEGER PRIMARY KEY,
  full_name   VARCHAR NOT NULL,
  city        VARCHAR,
  signup_date DATE,
  channel     VARCHAR
);
CREATE TABLE demo.products (
  product_id   INTEGER PRIMARY KEY,
  product_name VARCHAR NOT NULL UNIQUE,
  category     VARCHAR NOT NULL,
  price        DECIMAL(10,2) NOT NULL CHECK (price >= 0)
);
CREATE TABLE demo.orders (
  order_id    INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL REFERENCES demo.customers (customer_id),
  ordered_at  TIMESTAMP NOT NULL,
  status      VARCHAR NOT NULL CHECK (status IN ('delivered', 'shipped', 'cancelled', 'returned'))
);
CREATE TABLE demo.order_items (
  order_id   INTEGER NOT NULL REFERENCES demo.orders (order_id),
  line_no    INTEGER NOT NULL,
  product_id INTEGER NOT NULL REFERENCES demo.products (product_id),
  quantity   INTEGER NOT NULL CHECK (quantity > 0),
  PRIMARY KEY (order_id, line_no)
);

SELECT setseed(0.42);

INSERT INTO demo.customers
SELECT
  i AS customer_id,
  (['Ana', 'João', 'Maria', 'Pedro', 'Inês', 'Rui', 'Olga', 'Ivan', 'Sofia', 'Tiago', 'Elena', 'Marta'])[1 + (i * 7) % 12]
    || ' ' || (['Silva', 'Costa', 'Santos', 'Ferreira', 'Pereira', 'Oliveira', 'Rodrigues', 'Petrova', 'Martins', 'Sousa'])[1 + (i * 3) % 10] AS full_name,
  (['Lisbon', 'Porto', 'Braga', 'Coimbra', 'Faro', 'Madrid', 'Berlin'])[1 + (i * 5) % 7] AS city,
  DATE '2023-01-01' + CAST(floor(random() * 900) AS INTEGER) AS signup_date,
  (['email', 'ads', 'friend', 'social'])[1 + CAST(floor(random() * 4) AS INTEGER)] AS channel
FROM range(1, 201) t(i);

INSERT INTO demo.products
SELECT * FROM (VALUES
  (1, 'Espresso beans 1kg', 'Coffee', 18.50), (2, 'Filter coffee 500g', 'Coffee', 9.90),
  (3, 'Decaf 250g', 'Coffee', 7.20), (4, 'Green tea 100g', 'Tea', 5.40),
  (5, 'Earl Grey 100g', 'Tea', 4.80), (6, 'Chai mix 200g', 'Tea', 6.90),
  (7, 'Moka pot', 'Equipment', 34.00), (8, 'French press', 'Equipment', 27.50),
  (9, 'Hand grinder', 'Equipment', 49.00), (10, 'Milk frother', 'Equipment', 22.00),
  (11, 'Ceramic mug', 'Accessories', 8.00), (12, 'Travel cup', 'Accessories', 14.50),
  (13, 'Paper filters x100', 'Accessories', 3.20), (14, 'Almond biscotti', 'Snacks', 4.50),
  (15, 'Dark chocolate 85%', 'Snacks', 3.90), (16, 'Pastel de nata x6', 'Snacks', 7.80)
) AS p(product_id, product_name, category, price);

INSERT INTO demo.orders
SELECT
  i AS order_id,
  1 + CAST(floor(random() * 200) AS INTEGER) AS customer_id,
  TIMESTAMP '2024-01-01 08:00:00' + to_seconds(CAST(floor(random() * 365 * 86400) AS BIGINT)) AS ordered_at,
  (['delivered', 'delivered', 'delivered', 'delivered', 'shipped', 'cancelled', 'returned'])[1 + CAST(floor(random() * 7) AS INTEGER)] AS status
FROM range(1, 1501) t(i);

INSERT INTO demo.order_items
SELECT
  o.order_id,
  n AS line_no,
  1 + CAST(floor(random() * 16) AS INTEGER) AS product_id,
  1 + CAST(floor(random() * 3) AS INTEGER) AS quantity
FROM demo.orders o, range(1, 4) r(n)
WHERE n = 1 OR random() < 0.45;
`

export const WELCOME_SQL = `-- Welcome to Quaera Lab: DuckDB in your browser, nothing to install.
-- Run the query: Ctrl+Enter (runs the selection, or the whole tab).
-- Bring your own data: drop CSV / Excel files anywhere on the page.

SELECT
  p.category,
  count(DISTINCT o.order_id)            AS orders,
  sum(oi.quantity * p.price)            AS revenue
FROM demo.orders o
JOIN demo.order_items oi ON oi.order_id = o.order_id
JOIN demo.products    p  ON p.product_id = oi.product_id
WHERE o.status = 'delivered'
GROUP BY p.category
ORDER BY revenue DESC;
`

/** A new Python tab (stage 7): cells over the demo shop, with lab.table, lab.sql and a seaborn chart. */
export const PYTHON_STARTER = `# %% [markdown]
# Python in Quaera Lab: pandas, matplotlib and seaborn over the same tables as SQL.
# lab.table("demo.orders") gives a table as a DataFrame; lab.sql("SELECT …") runs SQL first;
# lab.save(df, "name") writes a DataFrame back as a table. A cell ends at the next # %% line (not at a semicolon).
# Run every cell: Ctrl+Enter · this cell, then on to the next: Shift+Enter.

# %%
import pandas as pd

orders = lab.table("demo.orders")
items = lab.table("demo.order_items")
products = lab.table("demo.products")
orders.head()

# %%
lines = items.merge(products, on="product_id").merge(orders, on="order_id")
lines["revenue"] = lines["quantity"] * lines["price"]
by_month = (
    lines[lines["status"] == "delivered"]
    .groupby([lines["ordered_at"].dt.to_period("M").dt.to_timestamp(), "category"])["revenue"]
    .sum()
    .reset_index()
)
by_month

# %%
import seaborn as sns
import matplotlib.pyplot as plt

sns.lineplot(data=by_month, x="ordered_at", y="revenue", hue="category")
plt.title("Delivered revenue by month")
plt.xticks(rotation=30)
plt.show()
`
